import java.io.ByteArrayInputStream
import java.util.Base64
import java.util.zip.InflaterInputStream

/**
 * High-Performance Curated English Corpus & Language Model for Clicksy Keyboard.
 * Contains ~10,000 top English words with frequency ranks, multi-word bigrams,
 * instant contraction expansions, spatial typo corrections, and inline emoji keywords.
 */
object EnglishDictionaryData {

    // Base64 compressed chunks of 10k English words dictionary
    private val DICTIONARY_CHUNKS = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    /**
     * Decompresses and streams all (word, frequency) pairs in the core dictionary.
     */
    fun loadWordFrequencies(onWord: (String, Int) -> Unit) {
        try {
            val fullBase64 = DICTIONARY_CHUNKS.joinToString("")
            val compressedBytes = Base64.getDecoder().decode(fullBase64)
            val inflaterStream = InflaterInputStream(ByteArrayInputStream(compressedBytes))
            inflaterStream.bufferedReader(Charsets.UTF_8).useLines { lines ->
                lines.forEach { line ->
                    val idx = line.lastIndexOf(':')
                    if (idx > 0) {
                        val word = line.substring(0, idx)
                        val freq = line.substring(idx + 1).toIntOrNull() ?: 1
                        onWord(word, freq)
                    }
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

